import React, { useState, useCallback } from 'react';
import { Message } from '../../types';
import MessageList from './MessageList';
import MessageInput from './MessageInput';
import LLMSettings from './LLMSettings';
import { useSpeechSynthesis } from '../../hooks/useSpeechSynthesis';
import { useLLM } from '../../hooks/useLLM';

const ChatContainer: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [conversationHistory, setConversationHistory] = useState<string[]>([]);
  const { speak, isSpeaking } = useSpeechSynthesis();
  const { generateResponse, isLoading, error: llmError, isConfigured } = useLLM();

  const handleSendMessage = useCallback(async (text: string) => {
    const userMessage: Message = {
      id: Date.now().toString(),
      text,
      timestamp: new Date(),
      isUser: true,
      type: 'text'
    };

    setMessages(prev => [...prev, userMessage]);

    // Update conversation history
    const newHistory = [...conversationHistory, text];
    setConversationHistory(newHistory);

    if (!isConfigured()) {
      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: "Please configure your LLM settings first. Click the settings button to get started.",
        timestamp: new Date(),
        isUser: false,
        type: 'text'
      };
      setMessages(prev => [...prev, errorMessage]);
      return;
    }

    try {
      // Generate AI response using the selected LLM
      const aiResponse = await generateResponse(text, conversationHistory);

      const aiMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: aiResponse.text,
        timestamp: new Date(),
        isUser: false,
        type: 'text'
      };

      setMessages(prev => [...prev, aiMessage]);

      // Update conversation history with AI response
      setConversationHistory(prev => [...prev, aiResponse.text]);

      // Speak the AI response
      await speak(aiResponse.text);

    } catch (error) {
      console.error('Error getting AI response:', error);

      const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        text: `Sorry, I encountered an error: ${error instanceof Error ? error.message : 'Unknown error'}`,
        timestamp: new Date(),
        isUser: false,
        type: 'text'
      };

      setMessages(prev => [...prev, errorMessage]);
    }
  }, [generateResponse, conversationHistory, speak, isConfigured]);

  return (
    <div className="chat-container">
      <div className="chat-header">
        <h2>AI Chatbot</h2>
        <div className="header-controls">
          <LLMSettings />
          {(isLoading || isSpeaking) && (
            <div className="status-indicator">
              {isLoading && <span>🤔 Thinking...</span>}
              {isSpeaking && <span>🔊 Speaking...</span>}
            </div>
          )}
        </div>
      </div>

      {llmError && (
        <div className="error-banner">
          <span>⚠️ {llmError}</span>
        </div>
      )}

      <MessageList messages={messages} />

      <MessageInput 
        onSendMessage={handleSendMessage}
        disabled={isLoading}
      />
    </div>
  );
};

export default ChatContainer;
